def transform(grid):
    h, w = len(grid), len(grid[0])
    g = [row[:] for row in grid]

    # Find the full row or column that acts as the boundary.
    line_color = 2
    line_row = next((r for r in range(h) if all(v == line_color for v in grid[r])), None)
    line_col = next((c for c in range(w) if all(grid[r][c] == line_color for r in range(h))), None)

    bg = max(set(v for row in grid for v in row), key=lambda v: sum(row.count(v) for row in grid))
    points = [(r, c, grid[r][c]) for r in range(h) for c in range(w)
              if grid[r][c] not in (bg, line_color)]
    if not points or (line_row is None and line_col is None):
        return g

    minr = min(r for r, c, v in points)
    maxr = max(r for r, c, v in points)
    minc = min(c for r, c, v in points)
    maxc = max(c for r, c, v in points)

    dr = dc = 0
    if line_row is not None:
        if maxr < line_row:
            dr = line_row - 1 - maxr
        elif minr > line_row:
            dr = line_row + 1 - minr
        marker = minr + dr - 1 if maxr < line_row else maxr + dr + 1
        for r in range(h):
            g[r] = [bg] * w
        for c in range(w):
            g[line_row][c] = line_color
        for r, c, v in points:
            g[r + dr][c] = v
        if 0 <= marker < h:
            for c in range(w):
                g[marker][c] = 8
    else:
        if maxc < line_col:
            dc = line_col - 1 - maxc
        elif minc > line_col:
            dc = line_col + 1 - minc
        marker = minc + dc - 1 if maxc < line_col else maxc + dc + 1
        for r in range(h):
            g[r] = [bg] * w
        for r in range(h):
            g[r][line_col] = line_color
        for r, c, v in points:
            g[r][c + dc] = v
        if 0 <= marker < w:
            for r in range(h):
                g[r][marker] = 8
    return g
